function drawHeart(x, y) {
	fill('rgb(229,100,173)');
	push();
	translate(x, y);
	push();
	scale(height / 640);
	beginShape();
	for (let a = 0; a <= TAU; a += (Math.max(0.001, Math.abs(TAU / 20)) || 1)) {
		let x1 = 6 * (sin(a) ** 3);
		let y1 = 6.5 * cos(a) - 2.5 * (cos(2 * a)) - (cos(3 * a)) - cos(4 * a) / 2;
		curveVertex(x1, y1);
	}
	endShape(CLOSE);
	pop();
	pop();
}

