function pineTree(x, y) {
	push();
	translate(x, y);
	for (let i = 0; i < 20; i++) {
		let a = map(i, 0, 20, -PI / 6, -HALF_PI);
		let yshift = map(i, 0, 20, 0, -height / 24);
		noFill();
		stroke('rgba(15,86,15,0.4)');
		strokeWeight(1);
		push();
		translate(0, yshift);
		rotate(a);
		line(0, 0, height / 128, 0);
		pop();
		push();
		translate(0, yshift);
		rotate(PI - a);
		line(0, 0, height / 128, 0);
		pop();
	}
	noStroke();
	fill('rgba(15,86,15,0.4)');
	ellipse(0, height / 120, height / 240, height / 60)
	arc(0, height / 60, height / 90, height / 120, PI, TWO_PI)
	pop();
}

