	translate(x, y);
	rotate(ang + HALF_PI);
	fill(color);
	ellipse(0, 0, sz, sz / 1.5);
	for (let a = -HALF_PI; a <= HALF_PI; a += (Math.max(0.001, Math.abs(PI / 5)) || 1)) {
		push();
		rotate(a);
		fill('rgba(255,0,0,0.59)');
