let mode = 2;

function preload() {
	img = loadImage('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/kushulan.png');
}

function setup() {
	createCanvas(windowWidth, windowHeight);
	imageMode(CENTER);
	translate(width / 2 + height / 600, height / 2);
	img.resize(0, height);
	scale(1.95);
	beginClip();
	rectMode(CENTER);
	rect(0, 0, height / 2, height / 2);
	endClip();
	switch (mode) {
		case 0:
			tint(255, 150);
			image(img, 0, 0);
			break;
		case 1:
			tint(255, 150);
			image(img, 0, 0);
			translate(-height / 600, 0);
			drawPiece();
			break;
		case 2:
			translate(-height / 600, 0);
			drawPiece();
			filter(BLUR, 1);
			break;
	}
}

